// The public home feed is regenerated by a repeatable job at the top of every
// hour (UTC) and once at boot, never inside a request. See
// docs/adr/0011-home-feed-architecture.md.

export const HOME_FEED_QUEUE = 'home-feed';
export const REFRESH_PUBLIC_HOME_FEED_JOB = 'refresh-public-home-feed';

/** The repeatable job's scheduler ID and cron (every hour, on the hour, UTC). */
export const PUBLIC_HOME_FEED_SCHEDULER_ID = 'refresh-public-home-feed-hourly';
export const PUBLIC_HOME_FEED_CRON = '0 * * * *';
